// The chevron next to YouTube's CC button and the panel it opens.
//
// Main view: Off, then the user's languages, each with how this video can show it (uploaded
// subtitles, auto-generated, auto-translated, or not at all). Edit view: search to add languages,
// reorder and remove them. YouTube's own CC button stays as it is and keeps toggling captions.
import { ask } from '../bridge/client';
import { CATALOGUE, canonical, type LanguageNames, namesOf, searchLanguages } from '../languages';
import { canAdd } from '../settings';
import { bestChoice, type Choice, currentLanguage, type PlayerState } from '../tracks';
import { el, icon } from './dom';
import { t } from './strings';
import { CHEVRON_CSS, PANEL_CSS } from './styles';

export const CHEVRON_HOST = 'my-subtitles-chevron';
export const PANEL_HOST = 'my-subtitles-panel';
export const OPEN_CLASS = 'my-subtitles-open';

export interface PickerOptions {
  player: HTMLElement;
  /** YouTube's CC button. */
  native: HTMLElement;
  languages: () => string[];
  setLanguages: (languages: string[]) => Promise<void>;
}

export interface Picker {
  readonly native: HTMLElement;
  readonly chevronHost: HTMLElement;
  /** Still in YouTube's control bar, right after the CC button? */
  attached(): boolean;
  languagesChanged(): void;
  /** Video changed: drop what we knew about the old one. */
  reset(): void;
  destroy(): void;
}

type View = 'main' | 'edit';
type Problem = 'not-ready' | 'failed' | null;

const HOW: Record<Choice['how'], string> = {
  subtitles: t.subtitles,
  'auto-generated': t.autoGenerated,
  'auto-translated': t.autoTranslated,
};

const sleep = (ms: number) => new Promise((resolve) => setTimeout(resolve, ms));

/** Events that must not reach YouTube's player (play/pause on click, shortcuts while typing…). */
const CONTAINED = ['click', 'dblclick', 'mousedown', 'mouseup', 'pointerup', 'contextmenu', 'wheel'];
const KEYS = ['keydown', 'keyup', 'keypress'];

export function mountPicker({ player, native, languages, setLanguages }: PickerOptions): Picker {
  const controller = new AbortController();
  const { signal } = controller;
  const on = <E extends Event>(
    target: EventTarget,
    type: string,
    handler: (event: E) => void,
    options: AddEventListenerOptions = {},
  ) => target.addEventListener(type, handler as EventListener, { ...options, signal });
  const uiLocale = navigator.language || 'en';

  // ── Chevron ────────────────────────────────────────────────────────────────────────────────
  const chevronHost = el('span', { class: CHEVRON_HOST });
  const chevronRoot = chevronHost.attachShadow({ mode: 'open' });
  const chevron = el('button', {
    type: 'button',
    'aria-haspopup': 'dialog',
    'aria-expanded': 'false',
    'aria-label': t.chevron,
    title: t.chevron,
  });
  chevron.append(icon('chevronUp'));
  chevronRoot.append(el('style', {}, CHEVRON_CSS), chevron);
  native.after(chevronHost);

  // ── Panel ──────────────────────────────────────────────────────────────────────────────────
  const panelHost = el('div', { class: PANEL_HOST });
  const root = panelHost.attachShadow({ mode: 'open' });
  const live = el('div', { class: 'status', role: 'status', 'aria-live': 'polite' });
  const panel = el('div', { class: 'panel', role: 'dialog', 'aria-label': t.panel });
  root.append(el('style', {}, PANEL_CSS), panel, live);
  player.append(panelHost);

  let open = false;
  let view: View = 'main';
  let state: PlayerState | null = null;
  let problem: Problem = null;
  let busy = false;
  let query = '';
  let generation = 0;
  let editList: HTMLElement | null = null;

  const names = (code: string): LanguageNames => {
    const fromVideo =
      state?.translations.find((l) => canonical(l.languageCode) === code)?.languageName ??
      state?.tracks.find((tr) => canonical(tr.languageCode) === code)?.displayName;
    return namesOf(code, uiLocale, fromVideo);
  };

  const announce = (text: string) => {
    live.textContent = '';
    live.textContent = text;
  };

  // ── Rows ───────────────────────────────────────────────────────────────────────────────────
  function label(code: string, withLocal: boolean) {
    const n = names(code);
    return el(
      'span',
      { class: 'label' },
      el('span', { class: 'name', lang: code }, n.native),
      withLocal && n.local ? el('span', { class: 'local' }, n.local) : null,
    );
  }

  function row(
    key: string,
    content: Node,
    detail: Node | string | null,
    pressed: boolean,
    disabled: boolean,
    onClick: () => void,
  ) {
    const button = el(
      'button',
      {
        type: 'button',
        class: 'row',
        'data-key': key,
        'aria-pressed': String(pressed),
        'aria-disabled': disabled ? 'true' : undefined,
      },
      el('span', { class: 'check' }, icon('check')),
      content,
      typeof detail === 'string' ? (detail ? el('span', { class: 'detail' }, detail) : null) : detail,
    );
    button.addEventListener('click', () => {
      if (!disabled) onClick();
    });
    return button;
  }

  // ── Views ──────────────────────────────────────────────────────────────────────────────────
  function mainView() {
    const view = el('div', { class: 'view' }, el('header', {}, el('h2', {}, t.title)));
    const list = el('div', { class: 'list' });
    const current = state ? currentLanguage(state.current) : null;
    const mine = languages();

    list.append(
      row('off', el('span', { class: 'label' }, t.off), null, !!state && !current, !state, turnOff),
    );

    if (current && !mine.includes(current)) {
      list.append(row(`now:${current}`, label(current, false), t.showingNow, true, true, () => {}));
    }

    for (const code of mine) {
      const choice = state ? bestChoice(code, state) : null;
      const detail = !state
        ? problem
          ? null
          : el('span', { class: 'detail loading', 'aria-hidden': 'true' })
        : !state.tracks.length
          ? null
          : choice
            ? HOW[choice.how]
            : t.notOnVideo;
      const button = row(`lang:${code}`, label(code, false), detail, current === code, !choice, () => {
        if (choice) void select(code, choice);
      });
      if (choice?.from) button.title = t.translatedFrom(choice.from.displayName);
      list.append(button);
    }
    view.append(list);

    if (problem) {
      const retry = el('button', { type: 'button', 'data-key': 'retry' }, t.retry);
      retry.addEventListener('click', () => void refresh());
      view.append(
        el('div', { class: 'note', role: 'alert' }, problem === 'failed' ? t.failed : t.notReady, retry),
      );
    } else if (state && !state.tracks.length) {
      view.append(el('div', { class: 'note' }, t.noSubtitles));
    }

    view.append(el('div', { class: 'separator' }));
    const edit = el(
      'button',
      { type: 'button', class: 'row', 'data-key': 'edit' },
      el('span', { class: 'check icon' }, icon(mine.length ? 'edit' : 'add')),
      el('span', { class: 'label' }, mine.length ? t.edit : t.addFirst),
    );
    edit.addEventListener('click', () => go('edit', 'forward'));
    view.append(edit);
    return view;
  }

  function editView() {
    const back = el('button', { type: 'button', class: 'back', 'aria-label': t.back, 'data-key': 'back' });
    back.append(icon('back'));
    back.addEventListener('click', () => go('main', 'backward', 'edit'));

    const input = el('input', {
      type: 'search',
      'aria-label': t.search,
      placeholder: t.searchPlaceholder,
      autocomplete: 'off',
      spellcheck: 'false',
      'data-key': 'search',
    });
    input.value = query;
    input.addEventListener('input', () => {
      query = input.value;
      fillEditList();
    });
    input.addEventListener('keydown', (event) => {
      if (event.key !== 'Enter') return;
      event.preventDefault();
      const first = query.trim() ? searchLanguages(query, candidates(), names)[0] : undefined;
      if (first && !languages().includes(first) && canAdd(languages())) {
        void toggle(first);
        query = '';
        input.value = '';
      }
    });

    editList = el('div', { class: 'list' });
    fillEditList();
    return el(
      'div',
      { class: 'view' },
      el('header', { class: 'with-back' }, back, el('h2', {}, t.yourLanguages)),
      el('label', { class: 'search' }, icon('search'), input),
      editList,
    );
  }

  /** Languages offered by search: this video's first, then all of YouTube's auto-translate targets. */
  function candidates(): string[] {
    const onVideo = state?.tracks.map((tr) => canonical(tr.languageCode)) ?? [];
    return [...new Set([...onVideo, ...Object.keys(CATALOGUE)])];
  }

  function fillEditList() {
    if (!editList) return;
    const focusedKey = focusKey();
    const mine = languages();
    editList.replaceChildren();

    if (query.trim()) {
      const results = searchLanguages(query, candidates(), names).slice(0, 60);
      const onVideo = new Set(state?.tracks.map((tr) => canonical(tr.languageCode)));
      for (const code of results) {
        const added = mine.includes(code);
        const button = row(
          `add:${code}`,
          label(code, true),
          onVideo.has(code) ? t.subtitles : null,
          added,
          !added && !canAdd(mine),
          () => void toggle(code),
        );
        button.title = added ? t.remove(names(code).native) : names(code).native;
        editList.append(button);
      }
      if (!results.length) editList.append(el('div', { class: 'note' }, t.noMatch));
    } else {
      mine.forEach((code, index) => {
        const name = names(code).native;
        const up = el('button', {
          type: 'button',
          class: 'tool',
          'aria-label': t.moveUp(name),
          title: t.moveUp(name),
          'data-key': `up:${code}`,
          disabled: index === 0,
        });
        up.append(icon('up'));
        up.addEventListener('click', () => void move(code));
        const remove = el('button', {
          type: 'button',
          class: 'tool',
          'aria-label': t.remove(name),
          title: t.remove(name),
          'data-key': `remove:${code}`,
        });
        remove.append(icon('close'));
        remove.addEventListener('click', () => void toggle(code));
        editList?.append(el('div', { class: 'edit-row' }, label(code, true), up, remove));
      });
      if (!mine.length) editList.append(el('div', { class: 'note' }, t.empty));
    }
    if (!canAdd(mine)) editList.append(el('div', { class: 'note' }, t.full));
    restoreFocus(focusedKey);
  }

  function render(direction: 'forward' | 'backward' | 'none' = 'none', focus?: string) {
    const focusedKey = focus ?? focusKey();
    editList = null;
    const next = view === 'main' ? mainView() : editView();
    if (direction !== 'none') next.classList.add(direction);
    panel.replaceChildren(next);
    if (open) position();
    restoreFocus(focusedKey);
  }

  function go(next: View, direction: 'forward' | 'backward', focus?: string) {
    view = next;
    if (next === 'edit') query = '';
    render(direction, focus ?? (next === 'edit' ? 'search' : undefined));
  }

  // ── Focus and keyboard ─────────────────────────────────────────────────────────────────────
  const focusables = () =>
    [...panel.querySelectorAll<HTMLElement>('button, input')].filter(
      (node) => !(node as HTMLButtonElement).disabled && node.getAttribute('aria-disabled') !== 'true',
    );

  const focusKey = () => (root.activeElement as HTMLElement | null)?.dataset.key;

  function restoreFocus(key: string | undefined) {
    if (!key || !open) return;
    const target = panel.querySelector<HTMLElement>(`[data-key="${CSS.escape(key)}"]`);
    if (target && !(target as HTMLButtonElement).disabled) target.focus();
    else if (key.startsWith('up:') || key.startsWith('remove:') || key.startsWith('add:')) {
      panel.querySelector<HTMLElement>('input')?.focus();
    }
  }

  function focusInitial() {
    const pressed = panel.querySelector<HTMLElement>('.row[aria-pressed="true"]:not([aria-disabled="true"])');
    (pressed ?? focusables()[0])?.focus();
  }

  on<KeyboardEvent>(panelHost, 'keydown', (event) => {
    // Escape closes from any view, also while typing a search (the ← button goes back).
    if (event.key === 'Escape') {
      event.preventDefault();
      close(true);
      return;
    }
    if (!['ArrowDown', 'ArrowUp', 'Home', 'End'].includes(event.key)) return;
    const inInput = root.activeElement instanceof HTMLInputElement;
    if (inInput && (event.key === 'Home' || event.key === 'End')) return;
    event.preventDefault();
    const items = focusables();
    if (!items.length) return;
    const index = items.indexOf(root.activeElement as HTMLElement);
    const next =
      event.key === 'Home'
        ? 0
        : event.key === 'End'
          ? items.length - 1
          : (index + (event.key === 'ArrowDown' ? 1 : -1) + items.length) % items.length;
    items[next]?.focus();
  });

  for (const type of [...CONTAINED, ...KEYS]) on(panelHost, type, (event) => event.stopPropagation());
  // Space/Enter on the chevron must not also play/pause the video.
  for (const type of KEYS) on(chevronHost, type, (event) => event.stopPropagation());
  on<KeyboardEvent>(chevronHost, 'keydown', (event) => {
    if (event.key === 'ArrowUp' && !open) {
      event.preventDefault();
      void openPanel();
    } else if (event.key === 'Escape' && open) {
      close(true);
    }
  });

  // ── Actions ────────────────────────────────────────────────────────────────────────────────
  async function refresh() {
    const token = generation;
    try {
      const next = await ask({ action: 'state' });
      if (token !== generation) return;
      state = next;
      problem = null;
    } catch {
      if (token !== generation) return;
      state = null;
      problem = 'not-ready';
    }
    if (open) {
      if (view === 'main') render();
      else fillEditList();
    }
  }

  async function select(code: string, choice: Choice) {
    if (busy) return;
    busy = true;
    const token = generation;
    try {
      let next = await ask({ action: 'select', vssId: choice.vssId, translateTo: choice.translateTo });
      // The player usually reports the new track at once; give it a moment if not.
      for (let i = 0; i < 10 && currentLanguage(next.current) !== code; i++) {
        await sleep(100);
        next = await ask({ action: 'state' });
      }
      if (token !== generation) return;
      state = next;
      if (currentLanguage(next.current) !== code) throw new Error('not switched');
      close(true);
    } catch {
      if (token !== generation) return;
      problem = 'failed';
      render();
    } finally {
      busy = false;
    }
  }

  function turnOff() {
    if (native.getAttribute('aria-pressed') === 'true') native.click();
    close(true);
  }

  async function toggle(code: string) {
    const mine = languages();
    const name = names(code).native;
    if (mine.includes(code)) {
      await setLanguages(mine.filter((c) => c !== code));
      announce(t.removed(name));
    } else if (canAdd(mine)) {
      await setLanguages([...mine, code]);
      announce(t.added(name));
    }
  }

  async function move(code: string) {
    const mine = languages();
    const index = mine.indexOf(code);
    if (index < 1) return;
    const next = [...mine];
    next.splice(index - 1, 0, ...next.splice(index, 1));
    await setLanguages(next);
  }

  // ── Open / close / position ────────────────────────────────────────────────────────────────
  function position() {
    const box = player.getBoundingClientRect();
    const anchor = (chevron.getClientRects().length ? chevron : native).getBoundingClientRect();
    const controls = player.querySelector('.ytp-chrome-bottom')?.getBoundingClientRect();
    const top = controls?.height ? Math.min(controls.top, anchor.top) : anchor.top;
    const bottom = Math.max(12, box.bottom - top + 6);
    const width = Math.min(300, box.width - 24);
    const right = Math.min(Math.max(12, box.right - anchor.right - 6), Math.max(12, box.width - width - 12));
    panelHost.style.right = `${right}px`;
    panelHost.style.bottom = `${bottom}px`;
    panel.style.width = `${width}px`;
    panel.style.setProperty('--max-height', `${Math.max(150, box.height - bottom - 12)}px`);
    const anchorFromRight = box.right - right - (anchor.left + anchor.width / 2);
    panel.style.setProperty('--anchor-offset', `${Math.max(12, Math.min(width - 12, anchorFromRight))}px`);
  }

  async function openPanel() {
    if (open) return;
    // One menu at a time: close YouTube's settings menu if it's open.
    const settings = player.querySelector<HTMLElement>('.ytp-settings-button');
    if (settings?.getAttribute('aria-expanded') === 'true') settings.click();
    open = true;
    view = 'main';
    problem = null;
    state = null;
    player.classList.add(OPEN_CLASS);
    chevron.setAttribute('aria-expanded', 'true');
    render();
    position();
    panel.classList.add('open');
    await refresh();
    if (open) focusInitial();
  }

  function close(returnFocus = false) {
    if (!open) return;
    open = false;
    panel.classList.remove('open');
    chevron.setAttribute('aria-expanded', 'false');
    player.classList.remove(OPEN_CLASS);
    if (returnFocus) chevron.focus();
  }

  on(chevron, 'click', (event) => {
    event.stopPropagation();
    if (open) close(true);
    else void openPanel();
  });

  on<PointerEvent>(
    document,
    'pointerdown',
    (event) => {
      const path = event.composedPath();
      if (open && !path.includes(panelHost) && !path.includes(chevronHost)) close();
    },
    { capture: true },
  );
  on(window, 'resize', () => open && position());
  on(document, 'fullscreenchange', () => open && position());

  // Captions turned on or off some other way (the CC button, the C key) while the panel is open.
  const observer = new MutationObserver(() => {
    if (open && !busy) void refresh();
  });
  observer.observe(native, { attributes: true, attributeFilter: ['aria-pressed'] });

  return {
    native,
    chevronHost,
    attached: () => native.isConnected && native.nextElementSibling === chevronHost && panelHost.isConnected,
    languagesChanged() {
      if (!open) return;
      if (view === 'main') render();
      else fillEditList();
    },
    reset() {
      generation++;
      state = null;
      close();
    },
    destroy() {
      generation++;
      close();
      controller.abort();
      observer.disconnect();
      chevronHost.remove();
      panelHost.remove();
    },
  };
}
